; beam.asm -- appendix D: where the VDP is on every line of the paper
; generated by genD.py
        INCLUDE "msx.inc"
        OUTPUT "beam.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
nwait   EQU VARS                ; lines of vwait: 119 at 50 Hz, 68 at 60 Hz
; The paper transparent: every pattern byte 0, every colour 0, so that the
; backdrop shows on the whole line. Each line of the paper gets a backdrop of
; its own, black and white in turn, written k T-states later in the line in
; turn k than in turn 0, k = 0 to 10 (measD.py reads the T-state of every
; write): the photograph shows where the VDP was.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $02          ; Graphic II
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $FF          ; colours            $2000
        VDP_REG 4, $03          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; backdrop
        VRAM_WRITE $0000        ; patterns: $00
        ld bc, 6144
.p:     ld a, $00
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .p
        VRAM_WRITE $2000        ; colours: $00
        ld bc, 6144
.c:     ld a, $00
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .c
        VRAM_WRITE $1800        ; names: 0 to 255 in each third
        ld b, 3
.n:     xor a
.n1:    out (VDP_DATA), a
        inc a
        jr nz, .n1
        djnz .n
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VDP_REG 1, $E0          ; display on, the frame interrupt on
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rlca
        ld a, 119
        jr c, hz50
        ld a, 68
hz50:   ld (nwait), a
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        ld b, $01               ; the value before the first turn's
        in a, (VDP_CTRL)        ; no signal left over from before
        ei
        halt                    ; one frame's interrupt: in step with the picture
        di
        DUP 20                  ; to turn 0: 243
        ld a, i
        EDUP
        ld d, 0
        DUP 3
        nop
        EDUP
t0:     call vwait
        DUP 4                   ; turn 0: 20 + 0: 20
        nop
        EDUP
        call lines
        DUP 30                  ; 340 - 0: 340
        ld a, i
        EDUP
        nop
        nop
        jp t1
t1:     call vwait
        ld a, i                 ; turn 1: 20 + 1: 21
        nop
        nop
        call lines
        DUP 29                  ; 340 - 1: 339
        ld a, i
        EDUP
        DUP 4
        nop
        EDUP
        jp t2
t2:     call vwait
        ld a, i                 ; turn 2: 20 + 2: 22
        ld a, i
        call lines
        DUP 30                  ; 340 - 2: 338
        ld a, i
        EDUP
        ld d, 0
        jp t3
t3:     call vwait
        ld d, 0                 ; turn 3: 20 + 3: 23
        DUP 3
        nop
        EDUP
        call lines
        DUP 29                  ; 340 - 3: 337
        ld a, i
        EDUP
        ld d, 0
        nop
        nop
        jp t4
t4:     call vwait
        ld a, i                 ; turn 4: 20 + 4: 24
        ld d, 0
        nop
        call lines
        DUP 28                  ; 340 - 4: 336
        ld a, i
        EDUP
        ld d, 0
        DUP 4
        nop
        EDUP
        jp t5
t5:     call vwait
        DUP 5                   ; turn 5: 20 + 5: 25
        nop
        EDUP
        call lines
        DUP 30                  ; 340 - 5: 335
        ld a, i
        EDUP
        nop
        jp t6
t6:     call vwait
        ld a, i                 ; turn 6: 20 + 6: 26
        DUP 3
        nop
        EDUP
        call lines
        DUP 29                  ; 340 - 6: 334
        ld a, i
        EDUP
        DUP 3
        nop
        EDUP
        jp t7
t7:     call vwait
        ld a, i                 ; turn 7: 20 + 7: 27
        ld a, i
        nop
        call lines
        DUP 28                  ; 340 - 7: 333
        ld a, i
        EDUP
        DUP 5
        nop
        EDUP
        jp t8
t8:     call vwait
        ld d, 0                 ; turn 8: 20 + 8: 28
        DUP 4
        nop
        EDUP
        call lines
        DUP 29                  ; 340 - 8: 332
        ld a, i
        EDUP
        ld d, 0
        nop
        jp t9
t9:     call vwait
        ld a, i                 ; turn 9: 20 + 9: 29
        ld d, 0
        nop
        nop
        call lines
        DUP 28                  ; 340 - 9: 331
        ld a, i
        EDUP
        ld d, 0
        DUP 3
        nop
        EDUP
        jp t10
t10:    call vwait
        ld a, i                 ; turn 10: 20 + 10: 30
        ld a, i
        ld d, 0
        call lines
        DUP 30                  ; 340 - 10: 330
        ld a, i
        EDUP
        jp t0

; lines: the paper's 192 lines, one turn of 228 T-states each
lines:  ld c, 192               ;  8
lp:     ld a, b                 ;  5: this line's backdrop
        out (VDP_CTRL), a       ; 12
        ld a, $87               ;  8
wr:     out (VDP_CTRL), a       ; 12: R#7
        ld a, b                 ;  5
        xor $0E                 ;  8: black, white
        ld b, a                 ;  5
        DUP 12                  ; the rest of the line: 157
        ld a, i
        EDUP
        DUP 5
        nop
        EDUP
        dec c                   ;  5
        jp nz, lp               ; 11: 228 a line
        ret                     ; 11

; vwait: WAIT_LINES lines of 228 T-states, as many as the machine needs
vwait:  ld a, (nwait)           ; 14
        ld e, a                 ;  5
vw:     DUP 17                  ; the rest of a line: 212
        ld a, i
        EDUP
        DUP 5
        nop
        EDUP
        dec e                   ;  5
        jp nz, vw               ; 11: 228 a turn
        ret                     ; 11

; isr: the frame's interrupt; reading the status takes the signal down
isr:    push af
        in a, (VDP_CTRL)
        pop af
        ei
        ret

        INCLUDE "tables.inc"
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
